const diagnose=()=>{if(!symptom.trim())return;const urgent=/smoke|fire|burn|isolation|overheat|high.voltage|swelling/i.test(symptom);const d={symptom,urgent,summary:urgent?'Potential high-voltage or thermal safety risk. Stop driving, move away to a safe location if possible, do not touch orange cables or the battery, and contact qualified emergency assistance.':'Several causes are possible. Arrange a qualified EV inspection and retrieve diagnostic trouble codes before replacing parts.'};setDiagnosis(d);notify('Preliminary triage completed')}
const submitService=async e=>{e.preventDefault();const record={id:'SR-'+Date.now().toString().slice(-7),...service,car:service.car||[garage.make,garage.model,garage.year].join(' '),diagnosis:diagnosis?.summary||'',status:'New request',createdAt:new Date().toISOString()};setServices(a=>[record,...a]);const msg='*EV PLACE — TECHNICIAN REQUEST*\nReference: '+record.id+'\nName: '+record.name+'\nPhone: '+record.phone+'\nLocation: '+record.location+'\nVehicle: '+record.car+'\nService: '+record.type+'\nDetails: '+(record.details||record.diagnosis||'Assessment requested');window.open('https://wa.me/'+WA+'?text='+encodeURIComponent(msg),'_blank','noopener,noreferrer');notify('Request prepared. Please send the WhatsApp message.')};
