const nav=['Showroom','Spare Parts','Backup Batteries','EV Doctor','Technicians'];
const saveOrder=async()=>{if(!cart.length)return;const record={id:'EVP-'+Date.now().toString().slice(-8),items:cart.map(x=>({id:x.id,name:x.model?x.make+' '+x.model:x.name,price:x.price,type:x.type})),total:cart.reduce((n,x)=>n+x.price,0),status:'New enquiry',customer:user?.email||'Guest',createdAt:new Date().toISOString()};setOrders(a=>[record,...a]);const msg='*EV PLACE — PRODUCT ENQUIRY*\nReference: '+record.id+'\nCustomer: '+record.customer+'\nItems:\n'+record.items.map(x=>'• '+x.name+' — '+money(x.price)).join('\n')+'\nIndicative total: '+money(record.total)+'\nPlease confirm current availability.';window.open('https://wa.me/'+WA+'?text='+encodeURIComponent(msg),'_blank','noopener,noreferrer');setCart([]);setDrawer('');notify('Enquiry prepared. Send the WhatsApp message to complete it.')};
const openAdmin=()=>{if(!isAdmin){notify('Administrator access is required. Sign in with an authorized admin account.');return}setView('admin');setActive('Overview');window.scrollTo({top:0,behavior:'smooth'})};
const apiAdmin=async(action,extra={})=>{setBusy(true);try{const r=await API('admin',{action,...extra});return r}catch(e){notify(e.message);throw e}finally{setBusy(false)}};
const testAstra=async()=>{try{const r=await apiAdmin('astra-test',{astra});setAstraStatus('Connected');notify(r.message||'Astra DB connection successful')}catch{setAstraStatus('Connection failed')}};
const syncAstra=async()=>{try{const r=await apiAdmin('astra-sync',{astra,products,orders,services});setAstraStatus('Synced just now');notify('Data sync completed: '+(r.synced??products.length)+' catalogue records')}catch{}};
const createProduct=()=>{const type=form.type||'vehicle';const p={...form,id:form.id||type+'-'+Date.now(),type,price:Number(form.price||0),stock:Number(form.stock||0),year:Number(form.year||2025),range:Number(form.range||0),battery:Number(form.battery||0),charge:Number(form.charge||0),capacity:Number(form.capacity||0),output:Number(form.output||0),status:form.status||'active',img:form.img||carImages[0],sku:form.sku||'EVP-'+Date.now().toString().slice(-7),condition:form.condition||'New'};setProducts(old=>form.id?old.map(x=>x.id===form.id?p:x):[p,...old]);setForm({});notify(form.id?'Product updated':'Product created')}
const archiveProduct=id=>{setProducts(a=>a.map(p=>p.id===id?{...p,status:'archived'}:p));notify('Product archived from the storefront')};
